/* Fixed-grant synchronous TinyEMU FSDevice adapter. MIT, project contribution.
 * Requires the guarded decoder; never use with unbounded upstream dispatch. */
#include <errno.h>
#include <pthread.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "cutils.h"
#include "fs.h"
#include "fs_grant.h"
#include "workspace_fids_abi.h"
typedef struct {FSDevice common;pthread_mutex_t mutex;void* root;char ticket[65];unsigned files;int retired;} GrantFs;
struct FSFile {GrantFs* owner;void* fid;int opened;int directory;int write_only;int can_write;};
static int error(void){int e=dsh_workspace_errno();return -(e?e:P9_EPERM);}
static int identity(void* fid,FSQID* qid){struct DshWorkspaceStat st;if(dsh_workspace_fid_stat(fid,&st))return error();qid->type=st.type==2?P9_QTDIR:P9_QTFILE;qid->version=0;qid->path=st.ino;return 0;}
static FSFile* file_new(GrantFs* fs,void* fid){if(!fid)return NULL;if(fs->files>=1024){dsh_workspace_fid_clunk(fid);return NULL;}FSFile*f=calloc(1,sizeof(*f));if(!f){dsh_workspace_fid_clunk(fid);return NULL;}f->owner=fs;f->fid=fid;fs->files++;return f;}
static void file_delete(FSDevice* common,FSFile*f){GrantFs*fs=(GrantFs*)common;dsh_workspace_fid_clunk(f->fid);fs->files--;free(f);}
static void file_close(FSDevice* common,FSFile*f){(void)common;(void)f;/* clunk owns final release; no early release of opened IO */}
static int attach(FSDevice* common,FSFile**out,FSQID*q,uint32_t uid,const char* uname,const char* aname){GrantFs*fs=(GrantFs*)common;(void)uid;(void)uname;if(aname[0])return -P9_EPERM;FSFile*f=file_new(fs,dsh_workspace_fid_clone(fs->root));if(!f)return -P9_EIO;int e=identity(f->fid,q);if(e){file_delete(common,f);return e;}*out=f;return 0;}
static int walk(FSDevice* common,FSFile**out,FSQID*q,FSFile*from,int count,char**names){GrantFs*fs=(GrantFs*)common;if(from->owner!=fs||count<0||count>16||from->opened)return -P9_EINVAL;void* fid=dsh_workspace_fid_clone(from->fid);if(!fid)return error();int i=0,e=0;for(;i<count;i++){void*next=dsh_workspace_fid_walk(fid,names[i]);if(!next){e=error();break;}dsh_workspace_fid_clunk(fid);fid=next;e=identity(fid,&q[i]);if(e)break;}if(e&&i==0){dsh_workspace_fid_clunk(fid);return e;}FSFile*f=file_new(fs,fid);if(!f)return -P9_EIO;*out=f;return i;}
static int open_file(FSDevice* common,FSQID*q,FSFile*f,uint32_t flags,FSOpenCompletionFunc*cb,void*opaque){(void)common;(void)cb;(void)opaque;const uint32_t allowed=3|P9_O_TRUNC|P9_O_LARGEFILE|P9_O_DIRECTORY|P9_O_NOFOLLOW|P9_O_CLOEXEC|P9_O_NONBLOCK|P9_O_NOCTTY;if(flags&~allowed||(flags&3)==3||f->opened)return -P9_EINVAL;struct DshWorkspaceStat st;if(dsh_workspace_fid_stat(f->fid,&st))return error();if((flags&P9_O_DIRECTORY)&&st.type!=2)return -P9_ENOTDIR;if(st.type==2){if((flags&3)||(flags&P9_O_TRUNC))return -P9_EPERM;f->directory=1;}else if(dsh_workspace_fid_open(f->fid,(flags&3)!=0,(flags&P9_O_TRUNC)!=0))return error();f->write_only=(flags&3)==1;f->can_write=(flags&3)!=0;f->opened=1;return identity(f->fid,q);}
static int create_file(FSDevice*common,FSQID*q,FSFile*f,const char*name,uint32_t flags,uint32_t mode,uint32_t gid){(void)common;(void)mode;(void)gid;const uint32_t allowed=3|P9_O_CREAT|P9_O_EXCL|P9_O_TRUNC|P9_O_LARGEFILE|P9_O_CLOEXEC|P9_O_NOFOLLOW;if(flags&~allowed||(flags&3)==3||f->opened)return -P9_EINVAL;void*next=dsh_workspace_fid_create(f->fid,name);if(!next)return error();dsh_workspace_fid_clunk(f->fid);f->fid=next;f->opened=1;f->write_only=(flags&3)==1;f->can_write=(flags&3)!=0;return identity(next,q);}
static int stat_file(FSDevice* common,FSFile*f,FSStat*out){(void)common;struct DshWorkspaceStat st;if(dsh_workspace_fid_stat(f->fid,&st))return error();memset(out,0,sizeof(*out));out->qid.type=st.type==2?P9_QTDIR:P9_QTFILE;out->qid.path=st.ino;out->st_mode=st.mode;out->st_uid=60081;out->st_gid=60081;out->st_nlink=1;out->st_size=st.size;out->st_blksize=4096;out->st_blocks=(st.size+511)/512;out->st_mtime_sec=(uint64_t)(st.mtime_ms/1000);return 0;}
static int read_file(FSDevice*c,FSFile*f,uint64_t o,uint8_t*b,int n){(void)c;if(n<0||!f->opened||f->directory||f->write_only)return -P9_EINVAL;int64_t r=dsh_workspace_fid_read(f->fid,o,b,n);return r<0?error():(int)r;}
static int write_file(FSDevice*c,FSFile*f,uint64_t o,const uint8_t*b,int n){(void)c;if(n<0||!f->opened||f->directory||!f->can_write)return -P9_EINVAL;int64_t r=dsh_workspace_fid_write(f->fid,o,b,n);return r<0?error():(int)r;}
static int mkdir_file(FSDevice*c,FSQID*q,FSFile*f,const char*n,uint32_t mode,uint32_t gid){(void)c;(void)mode;(void)gid;if(dsh_workspace_fid_mkdir(f->fid,n))return error();void* child=dsh_workspace_fid_walk(f->fid,n);if(!child)return error();int e=identity(child,q);dsh_workspace_fid_clunk(child);return e;}
static int rename_file(FSDevice*c,FSFile*f,const char*n,FSFile*to,const char*nn){(void)c;return dsh_workspace_fid_rename(f->fid,n,to->fid,nn)?error():0;}
static int unlink_file(FSDevice*c,FSFile*f,const char*n){(void)c;void*child=dsh_workspace_fid_walk(f->fid,n);if(!child)return error();struct DshWorkspaceStat st;int e=dsh_workspace_fid_stat(child,&st);dsh_workspace_fid_clunk(child);if(e)return error();return dsh_workspace_fid_remove(f->fid,n,st.type==2)?error():0;}
// Cookie is a bounded immutable per-call index. Concurrent directory mutation
// may change enumeration as with ordinary readdir; no authority derives from it.
struct Listing{FSFile*f;uint8_t*buf;int size,pos,full;uint64_t skip,index;};
static int entry(const char*name,size_t len,void*opaque){struct Listing*l=opaque;uint64_t index=l->index++;if(index<l->skip)return 0;if(l->full)return 0;if(l->pos+24+(int)len>l->size){l->full=1;return 0;}void*child=dsh_workspace_fid_walk(l->f->fid,name);if(!child)return 0;struct DshWorkspaceStat st;int e=dsh_workspace_fid_stat(child,&st);dsh_workspace_fid_clunk(child);if(e)return -1;uint8_t*b=l->buf+l->pos;b[0]=st.type==2?P9_QTDIR:P9_QTFILE;put_le32(b+1,0);put_le64(b+5,st.ino);put_le64(b+13,index+1);b[21]=st.mode>>12;put_le16(b+22,len);memcpy(b+24,name,len);l->pos+=24+len;return 0;}
static int readdir_file(FSDevice*c,FSFile*f,uint64_t offset,uint8_t*b,int n){(void)c;if(!f->opened||!f->directory||offset>10000||n<0)return -P9_EINVAL;struct Listing l={f,b,n,0,0,offset,0};return dsh_workspace_fid_list(f->fid,entry,&l)?error():l.pos;}
static void statfs_file(FSDevice*c,FSStatFS*out){(void)c;memset(out,0,sizeof(*out));out->f_bsize=4096;}
int fs_grant_request_begin(FSDevice* common,unsigned id){GrantFs*fs=(GrantFs*)common;pthread_mutex_lock(&fs->mutex);int e=0;if(fs->retired&&id!=120&&id!=108&&id!=100)e=P9_EPERM;else switch(id){case 8:case 12:case 14:case 24:case 40:case 72:case 74:case 76:case 100:case 104:case 108:case 110:case 116:case 118:case 120:break;default:e=P9_ENOTSUP;}if(e)pthread_mutex_unlock(&fs->mutex);return -e;}
void fs_grant_request_end(FSDevice*common){pthread_mutex_unlock(&((GrantFs*)common)->mutex);}
FSDevice* fs_grant_init(const char*ticket){if(!ticket||strlen(ticket)!=64)return NULL;GrantFs*fs=calloc(1,sizeof(*fs));if(!fs)return NULL;if(pthread_mutex_init(&fs->mutex,NULL)){free(fs);return NULL;}memcpy(fs->ticket,ticket,65);fs->root=dsh_workspace_fid_attach(ticket);if(!fs->root){pthread_mutex_destroy(&fs->mutex);free(fs);return NULL;}fs->common=(FSDevice){.fs_delete=file_delete,.fs_statfs=statfs_file,.fs_attach=attach,.fs_walk=walk,.fs_mkdir=mkdir_file,.fs_open=open_file,.fs_create=create_file,.fs_stat=stat_file,.fs_close=file_close,.fs_readdir=readdir_file,.fs_read=read_file,.fs_write=write_file,.fs_renameat=rename_file,.fs_unlinkat=unlink_file};return &fs->common;}
int fs_grant_retire(FSDevice*common){GrantFs*fs=(GrantFs*)common;int e=dsh_workspace_ticket_retire(fs->ticket);pthread_mutex_lock(&fs->mutex);fs->retired=1;pthread_mutex_unlock(&fs->mutex);return e<0?-P9_EIO:0;}
int fs_grant_destroy(FSDevice*common){GrantFs*fs=(GrantFs*)common;pthread_mutex_lock(&fs->mutex);if(!fs->retired||fs->files){pthread_mutex_unlock(&fs->mutex);return -16;}dsh_workspace_fid_clunk(fs->root);fs->root=NULL;int drained=dsh_workspace_ticket_retire(fs->ticket);pthread_mutex_unlock(&fs->mutex);if(drained!=1)return -P9_EIO;pthread_mutex_destroy(&fs->mutex);free(fs);return 0;}
